definition.script:
pipeline {
    agent any
    environment {
        VERSION = "v.2.0.${env.BUILD_ID}"
        NOMBRE = "Build ${env.JOB_NAME.toUpperCase()} ${VERSION}"
        SECRETO = credentials('SonarToken')
    }
    // parameters {
    //     string(name: 'Greeting', defaultValue: 'Hello', description: 'How should I greet the world?')
    //     booleanParam defaultValue: true, name: 'visible'
    // }
    triggers {
      cron 'H/15 * * * 1-5'
    }
    stages {
        stage('inicializo') {
            steps {
                echo NOMBRE
                echo SECRETO
                // echo "Clonar el repositorio ${params.Greeting} ${SECRETO}"
                echo "Clonar el repositorio ${SECRETO}"
            }
        }
        stage('compilo') {
            steps {
                echo "mvn compile ${VERSION}"
            }
        }
        stage('test') {
            steps {
                echo 'mvn test'
            }
        }
        stage('empaqueta') {
            steps {
                // sh 'cp /target/*.war /appserver'
                echo 'mvn package -DskipTests'
            }
        }
        stage('despliega') {
            steps {
                echo 'cp /target/*.war /appserver'
                // echo 'mvn intall -DskipTests'
            }
        }
    }
}
